def tau(n):
    """Computes the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Computes the number of positive divisors of n other than 1 and itself."""
    if n <= 1:
        return 0
    # d(n) = tau(n) - 2
    return tau(n) - 2

results = []
for n in range(1, 101):
    d_n = d(n)
    d_n_plus_735 = d(n + 735)

    if d_n == d_n_plus_735:
        a = d_n
        results.append((n, a))

print("Pairs (n, a) such that d(n) = d(n+735) = a:")
for n, a in results:
    print(f"n={n}, a={a}")

# Collect the unique 'a' values found, sorted.
a_values = sorted(list(set([a for n, a in results])))
print("\nUnique values of a found:", a_values)
